<?php
/** Proof — submit, approve, snapshots (spec "Proof", 3): Priya submits (Marco told); edits refused in words; Marco approves — 180 rate_card, cost 70, approved_by, the week approved, Priya told; self-approval; Dana (no time.approve) 403; a locked entry; approving twice. */
require __DIR__ . '/lib.php';
[$acme, $beta] = time_world();
$priya = as_member(26); $marco = as_member(27); $dana = as_member(30); $ann = as_member(29);
$w = monday(2); $ts = week_id(26, $w) ?? (function () use ($priya, $acme, $w) { log_time($priya, $acme, day($w, 0), '4'); return week_id(26, $w); })();
$num = (string) one('SELECT number FROM engagements WHERE id = :e', ['e' => $acme]);

echo "1. Submit\n";
[$c, $b] = act($priya, '/time/weeks/submit.php', ['week' => day(monday(0), 7)]);
ok($c === 422 && str_contains(msg($b), 'has not started'), 'a week in the future: 422 "has not started"');
$since = last_activity_id();
$outboxBefore = (int) one("SELECT count(*) FROM notification_outbox");
[$c, $b] = act($priya, '/time/weeks/submit.php', ['week' => $w]);
ok($c === 200 && ($b['status'] ?? '') === 'submitted' && q('SELECT status, submitted_at IS NOT NULL AS s FROM timesheets WHERE id = :t', ['t' => $ts])[0] === ['status' => 'submitted', 's' => true] && (int) one("SELECT count(*) FROM time_entries WHERE timesheet_id = :t AND status <> 'submitted'", ['t' => $ts]) === 0, 'timesheet_submit: the week and every entry submitted');
$log = activity('timesheet.submit', $since);
ok(count($log) === 1 && (int) $log[0]['timesheet_id'] === $ts && json_decode((string) $log[0]['after'], true)['member_id'] === 26 && json_decode((string) $log[0]['after'], true)['entries'] === 3, 'timesheet.submit logged with timesheet_id, the member and the entries');
$told = q("SELECT member_id, kind, record_id FROM notifications WHERE kind = 'timesheet_submitted' ORDER BY id DESC LIMIT 1");
ok($told === [['member_id' => 27, 'kind' => 'timesheet_submitted', 'record_id' => $ts]], 'Marco (the manager of the engagements in it) is told in-app');
ok((int) one("SELECT count(*) FROM notification_outbox WHERE kind = 'timesheet_submitted' AND member_id = 27") === 0, 'no email to him: timesheet_submitted is not among his default kinds (his settings decide)');
[$c, $b] = log_time($priya, $acme, day($w, 3), '1');
ok($c === 422 && msg($b) === 'The week of ' . day($w, 3) . ' is submitted — reopen it before adding time', 'an entry in a submitted week: the database\'s sentence (' . msg($b) . ')');
[$c, $b] = act($priya, '/time/entries/save.php', ['entry' => (int) one('SELECT id FROM time_entries WHERE timesheet_id = :t ORDER BY id LIMIT 1', ['t' => $ts]), 'hours' => '5']);
ok($c === 422 && (str_contains(msg($b), 'reopen it') || str_contains(msg($b), 'is submitted')), 'changing a submitted entry: refused in words (' . msg($b) . ')');
[$c, $b] = act($priya, '/time/weeks/submit.php', ['week' => $w]);
ok($c === 422 && msg($b) === 'The week of ' . $w . ' is already submitted', 'submitting again: "already submitted"');

echo "2. Approve: the snapshots\n";
[$c, $b] = act($priya, '/time/weeks/approve.php', ['timesheet' => $ts]);
ok($c === 403, 'Priya (no time.approve) may not approve at all: 403');
[$c, $b] = act($dana, '/time/weeks/approve.php', ['timesheet' => $ts]);
ok($c === 403 && msg($b) === 'You may not approve time.', 'Dana (a Consultant): 403 "You may not approve time."');
[$c, $d] = screen($marco, '/time/weeks/' . $ts);
$mon = $d['days'][0]['entries'][0];
ok($c === 200 && $mon['will_apply']['bill_rate'] === '180.00' && $mon['will_apply']['rate_source'] === 'rate_card' && $mon['bill_rate'] === null && $d['may']['approve'] === true, 'before approval Marco\'s view says the rate that WILL apply: 180.00 from the card');
$body = page($marco, '/time/weeks/' . $ts)['body'];
ok(str_contains($body, 'will apply 180.00 USD/h') && str_contains($body, 'id="week-approve-btn"') && str_contains($body, 'id="week-reject-form"'), 'the page shows "will apply 180.00 USD/h", Approve and Send back');
$since = last_activity_id();
[$c, $b] = act($marco, '/time/weeks/approve.php', ['timesheet' => $ts]);
ok($c === 200 && $b['approved'] === 3 && $b['left_submitted'] === 0 && $b['week_status'] === 'approved', 'timesheet_approve: 3 approved, nothing left, the week approved');
$rows = q('SELECT status, bill_rate, rate_source, consulting_role_id, cost_rate, approved_by, billable FROM time_entries WHERE timesheet_id = :t ORDER BY entry_date', ['t' => $ts]);
ok($rows[0] === ['status' => 'approved', 'bill_rate' => '180.00', 'rate_source' => 'rate_card', 'consulting_role_id' => role('consultant'), 'cost_rate' => '70.00', 'approved_by' => 27, 'billable' => true], 'Mon: approved at 180.00 (rate_card, Consultant), cost 70.00, approved_by Marco');
$travel = array_values(array_filter($rows, fn ($r) => !$r['billable']))[0];
ok($travel['bill_rate'] === null && $travel['rate_source'] === 'none' && $travel['cost_rate'] === '70.00', 'the non-billable travel entry: no bill rate (source none), the cost still snapshotted');
ok(q('SELECT status, approved_by, approved_at IS NOT NULL AS a FROM timesheets WHERE id = :t', ['t' => $ts])[0] === ['status' => 'approved', 'approved_by' => 27, 'a' => true], 'the week: approved by Marco');
$log = activity('timesheet.approve', $since);
ok(count($log) === 1 && json_decode((string) $log[0]['after'], true)['approved'] === 3 && !str_contains((string) $log[0]['after'], '180') && !str_contains((string) $log[0]['after'], '70.00'), 'timesheet.approve logged (approved, left_submitted) — no rate or cost in the log');
ok(q("SELECT member_id FROM notifications WHERE kind = 'timesheet_approved' ORDER BY id DESC LIMIT 1") === [['member_id' => 26]], 'Priya is told her week was approved');
[$c, $b] = act($marco, '/time/weeks/approve.php', ['timesheet' => $ts]);
ok($c === 422 && msg($b) === 'The week of ' . $w . ' is approved, not submitted', 'approving twice: 422 in the verb\'s words');
[$c, $b] = act($priya, '/time/entries/save.php', ['entry' => (int) one('SELECT id FROM time_entries WHERE timesheet_id = :t ORDER BY id LIMIT 1', ['t' => $ts]), 'hours' => '5']);
ok($c === 422 && str_contains(msg($b), 'is approved'), 'an approved entry\'s edit: refused in words (' . msg($b) . ')');
[$c, $b] = act($priya, '/time/entries/delete.php', ['entry' => (int) one('SELECT id FROM time_entries WHERE timesheet_id = :t ORDER BY id LIMIT 1', ['t' => $ts])]);
ok($c === 422 && msg($b) === 'A approved time entry is never deleted', 'its delete: the trigger\'s words');
[$c, $b] = log_time($priya, $acme, day($w, 3), '1');
ok($c === 422 && msg($b) === 'The week of ' . day($w, 3) . ' is approved — reopen it before adding time', 'an entry in an approved week: the same sentence with "approved" (' . msg($b) . ')');
[$c, $d] = screen($priya, '/time/?week=' . $w);
ok($d['days'][0]['entries'][0]['bill_rate'] === null && $d['days'][0]['entries'][0]['cost_rate'] === null && $d['status'] === 'approved', 'Priya still sees no rate or cost on her approved entries');
[$c, $d] = screen($marco, '/time/weeks/' . $ts);
ok($d['days'][0]['entries'][0]['bill_rate'] === '180.00' && $d['days'][0]['entries'][0]['bill_value'] === '720.00' && $d['days'][0]['entries'][0]['cost_rate'] === '70.00', 'Marco sees the snapshot: 180.00, value 720.00, cost 70.00 (his engagement)');
[$c, $d] = screen($ann, '/time/weeks/' . $ts);
ok($c === 200 && $d['days'][0]['entries'][0]['cost_rate'] === '70.00' && $d['may']['approve'] === false, 'Ann (Finance) reads it with the cost, may not approve');

echo "3. Self-approval and the super-admin\n";
$wm = monday(3);
[$c, $b] = act($marco, '/time/entries/save.php', ['engagement' => $acme, 'date' => day($wm, 0), 'hours' => '2']);
ok($c === 200, 'Marco logs on his own engagement (its manager may)');
[$c, $b] = act($marco, '/time/weeks/submit.php', ['week' => $wm]);
$tsm = week_id(27, $wm);
[$c, $b] = act($marco, '/time/weeks/approve.php', ['timesheet' => $tsm]);
ok($c === 422 && msg($b) === 'Nobody approves their own time', 'self-approval: 422 "Nobody approves their own time"');
[$c, $b] = act(as_member(1), '/time/weeks/approve.php', ['timesheet' => $tsm]);
ok($c === 200 && $b['week_status'] === 'approved' && (string) one('SELECT bill_rate FROM time_entries WHERE timesheet_id = :t', ['t' => $tsm]) === '300.00', 'the super-admin approves it: 300.00 (Principal from the card)');
finish();
